fn gcd(a: Int, b: Int) -> Int {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn main() {
    print(gcd(252, 105))
}

fn gcd(a: Int, b: Int) -> Int {
    let mut tmp;
    if a < b {
        tmp = a;
        a = b;
        b = tmp;
    }
    while b != 0 {
        tmp = a % b;
        a = b;
        b = tmp;
    }
    a
}

fn main() {
    let a = 252;
    let b = 105;
    let result = gcd(a, b);
    print(result);
}

